  "$schema": "http://json-schema.org/draft-07/schema",
  "$id": "http://example.com/example.json",
  "type": "object",
  "title": "Root",
  "default": {},
  "required": [
    "global",
    "orgs",
    "channels",
    "chaincodes"
  ],
  "properties": {
    "$schema": {
      "const": "https://github.com/hyperledger-labs/fablo/releases/download/2.6.0/schema.json"
    },
    "global": {
      "$id": "#/properties/global",
      "title": "Global network settings",
      "description": "Basic settings of the Hyperledger Fabric network",
      "type": "object",
      "required": [
        "fabricVersion",
        "tls"
      ],
      "properties": {
        "fabricVersion": {
          "$id": "#/properties/global/properties/fabricVersion",
          "title": "Hyperledger Fabric version",
          "type": "string",
          "default": "2.4.2"
        },
        "tls": {
          "$id": "#/properties/global/properties/tls",
          "title": "Use TLS",
          "type": "boolean",
          "default": true
        },
        "peerDevMode": {
          "$id": "#/properties/global/properties/peerDevMode",
          "title": "Start all peers in dev mode",
          "type": "boolean",
          "default": false
        },
        "fabricImages": {
          "$id": "#/properties/global/properties/fabricImages",
          "title": "Fabric image repositories",
          "description": "Optional Docker images for Hyperledger Fabric components",
          "type": "object",
          "required": [],
          "properties": {
            "peer": {
              "$id": "#/properties/global/properties/fabricImages/properties/peer",
              "title": "Peer image",
              "type": "string",
              "default": "hyperledger/fabric-peer"
            },
            "orderer": {
              "$id": "#/properties/global/properties/fabricImages/properties/orderer",
              "title": "Orderer image",
              "type": "string",
              "default": "hyperledger/fabric-orderer"
            },
            "ca": {
              "$id": "#/properties/global/properties/fabricImages/properties/ca",
              "title": "CA image",
              "type": "string",
              "default": "hyperledger/fabric-ca"
            },
            "tools": {
              "$id": "#/properties/global/properties/fabricImages/properties/tools",
              "title": "Tools image",
              "type": "string",
              "default": "hyperledger/fabric-tools"
            },
            "ccenv": {
              "$id": "#/properties/global/properties/fabricImages/properties/ccenv",
              "title": "CCENV image",
              "type": "string",
              "default": "hyperledger/fabric-ccenv"
            },
            "baseos": {
              "$id": "#/properties/global/properties/fabricImages/properties/baseos",
              "title": "BaseOS image",
              "type": "string",
              "default": "hyperledger/fabric-baseos"
            },
            "javaenv": {
              "$id": "#/properties/global/properties/fabricImages/properties/javaenv",
              "title": "Javaenv image",
              "type": "string",
              "default": "hyperledger/fabric-javaenv"
            },
            "nodeenv": {
              "$id": "#/properties/global/properties/fabricImages/properties/nodeenv",
              "title": "Nodeenv image",
              "type": "string",
              "default": "hyperledger/fabric-nodeenv"
            }
          }
        },
        "engine": {
          "$id": "#/properties/global/properties/engine",
          "title": "Engine on which the network will be deployed",
          "type": "string",
          "enum": [
            "docker",
            "kubernetes"
          ],
          "default": "docker"
        },
        "monitoring": {
          "$id": "#/properties/monitoring",
          "title": "Monitoring settings",
          "description": "Optional settings for monitoring purposes",
          "type": "object",
          "required": [],
          "properties": {
            "loglevel": {
              "$id": "#/properties/monitoring/properties/loglevel",
              "title": "Log level for all components",
              "type": "string",
              "enum": [
                "debug",
                "info",
                "warn"
              ],
              "default": "info"
            }
          }
        },
        "tools": {
          "$id": "#/properties/global/properties/tools",
          "type": "object",
          "title": "Tools",
          "required": [],
          "properties": {
            "explorer": {
              "$id": "#/properties/global/properties/tools/properties/explorer",
              "title": "Blockchain Explorer enabled",
              "type": "boolean"
            }
          }
        }
      }
    },
    "orgs": {
      "$id": "#/properties/orgs",
      "title": "Organizations",
      "type": "array",
      "default": [
        {
          "organization": {
            "name": "Orderer",
            "mspName": "OrdererMSP",
