      "items": {
        "$id": "#/properties/orgs/items",
        "title": "Organization",
        "type": "object",
        "required": [
          "organization"
        ],
        "properties": {
          "organization": {
            "$id": "#/properties/orgs/items/properties/organization",
            "title": "Basic information",
            "type": "object",
            "required": [
              "name",
